Lemma art_qlist_trf : forall (M M' : word -> option byte) bs f l,
  (forall b, In b bs -> forall a (k : nat) v, qb_addr b <= a -> a + Z.of_nat k <= qb_addr b + 8192 -> cellA M a k v -> cellA M' a k v) ->
  art_qlist M bs f l -> art_qlist M' bs f l.
